function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const yes = function (x) { return s(x).toLowerCase() === 'yes'; };
const ih = (($('GET INV header').first().json.values || [[]])[0] || []).map(s);
const ph = (($('GET PIPE header').first().json.values || [[]])[0] || []).map(s);
const IC = {}; for (const h of ['investor', 'contact_person', 'email', 'cc', 'sector', 'stage', 'cheque_inr_cr']) { const i = ih.indexOf(h); if (i < 0) { throw new Error('ABORT: INVESTORS column missing ' + h); } IC[h] = colLetter(i); }
const PE = ph.indexOf('email'); if (PE < 0) { throw new Error('ABORT: PIPELINE email column missing'); }
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (inv.length < 200) { throw new Error('ABORT: INVESTORS only ' + inv.length); }
if (pipe.length < 4600) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
// new investors the user added to the composition sheet on 11 Sep (values cleaned for the matcher)
// user 11 Sep: Sayan Ghosh is a separate angel; OG Capital is a different investor
const NEW = [
  { investor: 'Sayan Ghosh', contact_person: 'Sayan', email: 'sayan@ogcapital.one', cc: '', sector: 'Sector agnostic (prefers SaaS, consumer tech, fintech)', stage: 'Pre-seed, Seed', cheque_inr_cr: '' }
];
const NEW_NI1 = [
  { investor: 'Gautham Krishnan', contact_person: 'Gautham', email: 'gauthamsdesk@gmail.com', cc: '', sector: 'Sector agnostic', stage: 'Pre-seed, Seed', cheque_inr_cr: '' },
  { investor: 'Z2O Studio & Fund', contact_person: 'Satyakam', email: 'satyakam@wyser.vc', cc: '', sector: 'Technology / tech-enabled businesses (sector agnostic within tech)', stage: 'Early stage', cheque_inr_cr: 'INR 1-4 Cr' },
  { investor: 'Pentathlon Ventures', contact_person: 'Sandeep Chawda', email: 'pipeline@pentathlon.vc', cc: '', sector: 'Sector agnostic - B2B focused (preferred: Enterprise AI, HealthTech, FinTech, Cybersecurity, Manufacturing / Logistics)', stage: 'Seed, Pre-Series A', cheque_inr_cr: 'US$500K-1M' },
  { investor: 'Sorenson Capital', contact_person: 'Grace', email: 'grace@sorensoncap.com', cc: '', sector: 'B2B Software - Cybersecurity, AI, Application Software, DevTools & Infrastructure', stage: 'Early stage to Growth / Pre-IPO', cheque_inr_cr: 'US$1-10M' },
  { investor: 'Henkel Ventures', contact_person: 'Aman Sharma', email: 'aman.sharma@henkel.com', cc: '', sector: 'Climate Tech, Deep Tech, Enterprise Tech, Consumer Tech - sustainable materials & ingredients, recycling, packaging, industrial tech, AI/software, commerce/MarTech/AdTech', stage: 'Early stage up to Series B', cheque_inr_cr: 'INR 4.5-45 Cr' },
  { investor: 'Sofinnova Partners', contact_person: 'Mariam Cherifi', email: '', cc: '', sector: 'Life Sciences, Biopharma, Medtech, Digital Medicine, Industrial Biotech', stage: 'Seed, Early stage to Later stage / Growth', cheque_inr_cr: 'INR 15-25 Cr' },
  { investor: 'InCred Capital', contact_person: 'Saumya', email: 'saumya.mittal@incredcapital.com', cc: '', sector: '', stage: '', cheque_inr_cr: '' }
];
const have = {}; for (const r of inv) { have[nz(r.investor)] = r; }
const appends = NEW.filter(function (n) { return !have[nz(n.investor)]; });
const skipped = NEW.filter(function (n) { return have[nz(n.investor)]; }).map(function (n) { return n.investor; });
// user edits in the composition sheet (Antler, SparkSeed)
const EDIT = { ogcapital: { contact_person: 'Shrinidhi', email: 'shrinidhi@ogcapital.one', cc: 'pitch@ogcapital.one', cheque_inr_cr: 'US$1-10M', stage: 'Seed to Pre-IPO', sector: 'B2C / ecommerce, retail, media & entertainment, enterprise' } };
const EDIT_NI1 = { antler: { contact_person: 'Anshul', email: 'anshul@antler.co', cheque_inr_cr: 'US$425K', stage: 'Day 0, Pre-seed, Seed', sector: 'Sector agnostic - focus: AI, Enterprise SaaS, Consumer, FinTech, Climate, DeepTech, Health' },
  sparkseedventures: { email: 'ashwani@sparkseedventures.in' } };
const data = [], editLog = [];
for (const k of Object.keys(EDIT)) { const rs = inv.filter(function (r) { return nz(r.investor) === k; });
  if (rs.length !== 1) { throw new Error('ABORT: ' + k + ' resolves to ' + rs.length + ' INVESTORS rows'); }
  const r = rs[0];
  for (const f of Object.keys(EDIT[k])) { if (s(r[f]) === EDIT[k][f]) { continue; }
    data.push({ range: 'INVESTORS!' + IC[f] + r.row_number, values: [[EDIT[k][f]]] }); editLog.push([s(r.investor), f, s(r[f]), EDIT[k][f]]); } }
// queued (unsent, unpaused) deals must carry the new address - outreach reads the email on the PIPELINE row
const pdata = [], repointed = [];
const NEWMAIL = { ogcapital: 'shrinidhi@ogcapital.one' };
for (const p of pipe) { const k = nz(p.investor); if (!NEWMAIL[k] || yes(p.deal_shared) || yes(p.pause)) { continue; }
  if (s(p.email).toLowerCase() === NEWMAIL[k]) { continue; }
  pdata.push({ range: 'PIPELINE!' + colLetter(PE) + p.row_number, values: [[NEWMAIL[k]]] }); repointed.push([p.row_number, s(p.deal_id), s(p.startup), s(p.investor), s(p.email)]); }
if (appends.length > 8) { throw new Error('ABORT: too many appends'); }
if (repointed.length > 80) { throw new Error('ABORT: ' + repointed.length + ' PIPELINE email changes exceeds guard'); }
if (!data.length) { data.push({ range: 'INVESTORS!' + IC.investor + '1', values: [['investor']] }); }
if (!pdata.length) { pdata.push({ range: 'PIPELINE!' + colLetter(PE) + '1', values: [['email']] }); }
return [{ json: { inv_before: inv.length, appends: appends, skipped_existing: skipped, edits: editLog, data: data, pdata: pdata, repointed: repointed } }];

const a = $('Plan').first().json.appends || [];
if (!a.length) { return [{ json: { __none: true } }]; }
return a.map(function (r) { return { json: r }; });

function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const plan = $('Plan').first().json;
const inv = $input.all().map(function (i) { return i.json; });
const want = ['sayanghosh'];
const present = want.map(function (k) { const r = inv.filter(function (x) { return nz(x.investor) === k; }); return [k, r.length, r.length ? s(r[0].email) : '']; });
const ant = inv.filter(function (x) { return nz(x.investor) === 'antler'; }).map(function (r) { return [r.row_number, s(r.contact_person), s(r.email), s(r.cheque_inr_cr), s(r.stage)]; });
const sp = inv.filter(function (x) { return nz(x.investor) === 'ogcapital'; }).map(function (r) { return [r.row_number, s(r.contact_person), s(r.email), s(r.cc), s(r.cheque_inr_cr), s(r.stage), s(r.sector)]; });
return [{ json: { inv_after: inv.length, expected: plan.inv_before + plan.appends.length, present: present, antler: ant, sparkseed: sp, edits: plan.edits, repointed: plan.repointed.length, skipped_existing: plan.skipped_existing,
  ok: inv.length === plan.inv_before + plan.appends.length && present.every(function (p) { return p[1] === 1; }) } }];
